// Normaliza el nivel de Oracle a vocabulario controlado (minusculas, sin tildes ni espacios),
// mismo criterio que scibackAbsenceType. Medido en PROD 29-oct-2026 sobre 17.814 estudiantes:
//   Pregrado 15.173 · Segunda Especialidad 978 · Posgrado 603 · CEPRE 462 · Idiomas 238
//   Conservatorio de Musica 234 · Doctorado 61 · Diplomatura 35 · Tesis 27
//   (+3 sucios: 'pregrado', 'posgrado' y 1 vacio — los absorbe el toLowerCase)
// SIN DEFAULT a proposito: un nivel no previsto deja el atributo AUSENTE. Imputar un nivel
// decidiria mal una tarifa de salud (precedente: el getOrDefault(v,'LIMA') del campus).
if (studyLevel == null) return null
def v = studyLevel.toString().trim().toLowerCase()
if (v == '') return null
v = java.text.Normalizer.normalize(v, java.text.Normalizer.Form.NFD).replaceAll('\\p{M}', '')
def mapa = [
  'pregrado'                : 'pregrado',
  'posgrado'                : 'posgrado',
  'doctorado'               : 'doctorado',
  'segunda especialidad'    : 'segunda-especialidad',
  'cepre'                   : 'cepre',
  'idiomas'                 : 'idiomas',
  'conservatorio de musica' : 'conservatorio',
  'diplomatura'             : 'diplomatura',
  'tesis'                   : 'tesis'
]
return mapa[v]
